
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbe_r_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbe_r", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.305585031244076e+00, -4.223989562180495e+00, -4.109779841725895e+00, -3.951835356108810e+00, -3.737177377293573e+00, -3.452683169323040e+00, -3.089073862725517e+00, -2.648037857965774e+00, -2.151168906521903e+00, -1.638340830202845e+00, -1.118667218262137e+00, -7.118799306895601e-01, -6.022384928314952e-01, -5.022743146841739e-01, -3.742964912317385e-01, -2.533560169511876e-01, -1.511905113816897e-01, -6.063035142073748e-02, -1.344398606371837e-02, -1.513494955500603e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


